/// Check whether a path has a `.toml` extension.
fn is_toml_path(path: &Path) -> bool {
    path.extension().is_some_and(|ext| ext == "toml")
}

/// Read file contents, mapping IO errors to domain errors.
fn read_file(path: &Path) -> Result<String> {
    fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })
}

/// Convert a `toml::Value` into a `serde_yaml::Value` for merge compatibility.
///
/// Routes through `serde_json::Value` as a common intermediate format
/// because both `toml` and `serde_yaml` support lossless JSON round-trips.
fn toml_to_yaml_value(toml_val: &toml::Value) -> std::result::Result<serde_yaml::Value, String> {
    let json = serde_json::to_value(toml_val).map_err(|e| e.to_string())?;
    serde_yaml::to_value(&json).map_err(|e| e.to_string())
}

/// Load a single config file and parse it into BivvyConfig.
///
/// Supports both YAML (`.yml`) and TOML (`.toml`) files, detected by
/// file extension.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the content is invalid.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = read_file(path)?;

    if is_toml_path(path) {
        parse_toml_config(&content, path)
    } else {
        parse_config(&content, path)
    }
}

/// Parse YAML content into BivvyConfig.
///
/// # Arguments
///
/// * `content` - The YAML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Parse TOML content into BivvyConfig.
///
/// Converts TOML → serde_yaml::Value → BivvyConfig so that fields
/// typed as `serde_yaml::Value` (e.g. step inputs) deserialize correctly.
fn parse_toml_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    let toml_val: toml::Value =
        toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: e.to_string(),
        })?;

    let yaml_val = toml_to_yaml_value(&toml_val).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e,
    })?;

    serde_yaml::from_value(yaml_val).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Load a config file as raw YAML Value (for merging).
///
/// Returns the raw `serde_yaml::Value` without deserializing into
/// `BivvyConfig`, which allows for deep merging before final parsing.
/// Supports both YAML and TOML files.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = read_file(path)?;

    if is_toml_path(path) {
        let toml_val: toml::Value =
            toml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })?;
        toml_to_yaml_value(&toml_val).map_err(|e| BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: e,
        })
    } else {
        serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: e.to_string(),
        })
    }
}

